  const platformNames={autoruns:'Sysinternals Autoruns',sigcheck:'Sysinternals Sigcheck',tshark:"TShark capture",windows:"Windows",linux:"Linux",fortinet:"Fortinet FortiOS",paloalto:"Palo Alto PAN-OS",checkpoint:"Check Point","cisco-ios":"Cisco IOS / IOS XE","cisco-asa":"Cisco ASA / FTD",unrecognized:"?"};
  Object.assign(words.en,{"lead": "Review Windows, Linux and network-device logs, reconstruct a timeline and inspect evidence behind suspicious patterns.", "files": "Local XML / JSON / NDJSON / CSV / syslog files", "formatsHint": "Up to 8 files, 10 MiB combined and 20,000 events. Native log subsets: Windows, Linux, FortiOS, PAN-OS, Check Point Log Exporter, Cisco ASA/FTD and IOS/IOS XE. Use the table below for the supported formats. Binary EVTX requires conversion; arbitrary SIEM, CEF/LEEF and custom vendor formats are not inferred.", "schemaHint": "Windows uses eventId, provider, channel and data. Reusable v2 events also carry platform. Vendor JSON/CSV uses the documented source fields or an explicit source selection. Use timestamps with Z/offset. Local syslog/PAN-OS dates need the correct UTC offset; legacy syslog also needs the year.", "sourceMode": "Log source", "autoSource": "Automatic detection", "contextLabel": "Import context for incomplete timestamps / host", "contextHint": "Optional. Supply the real UTC offset and year of the exported records, not your browser timezone. These values apply to every file in this run, only where missing; split imports if devices use different local offsets. An offset is fixed and does not infer daylight-saving changes. Missing context excludes events from time correlations.", "timezone": "UTC offset (example +03:00)", "year": "Year for legacy syslog", "evidenceHost": "Host when absent from the log", "platform": "Platform", "platformGuide": "Source coverage", "linuxCollect": "Read-only Linux export", "linuxCollectHint": "Export already collected local journals. SSH/sudo content and auditd records depend on the logging available on that system. Use a bounded time interval appropriate to your case.", "linuxDemo": "Linux SSH / sudo lab", "fortinetDemo": "FortiOS lab", "paloaltoDemo": "PAN-OS lab", "checkpointDemo": "Check Point lab", "cisco-iosDemo": "Cisco IOS / IOS XE lab", "cisco-asaDemo": "Cisco ASA / FTD lab", "sourceCounts": "Imported platforms", "windowsScope": "Security, Sysmon, PowerShell and Defender XML/JSON/CSV. Binary EVTX needs conversion.", "linuxScope": "journalctl JSON/NDJSON; sshd/sudo syslog; auditd USER_AUTH, USER_LOGIN, USER_CMD and CONFIG_CHANGE. Other audit records remain context, without stitching kernel events.", "fortinetScope": "FortiOS key=value text or equivalent flat JSON/CSV: admin login, configuration, denied traffic and selected UTM events.", "paloaltoScope": "Default PAN-OS syslog CSV: SYSTEM, CONFIG, TRAFFIC and THREAT; equivalent named JSON/CSV. Custom positional formats are not mapped. System authentication prose stays context.", "checkpointScope": "Log Exporter flat JSON/CSV or semicolon key:value syslog with Check Point selected. Threat/denied traffic review; audit records remain context. No CEF/LEEF or SmartConsole binary files.", "ciscoScope": "ASA/FTD %ASA/%FTD messages and IOS/IOS XE %SEC_LOGIN, %SYS-CONFIG_I, %PARSER-CFGLOG_LOGGEDCMD. Selected AAA, denied-traffic and command events; no universal Cisco/ISE/FMC import.", "contextCounts": "Events with supplied import context"});
