  Object.assign(rules.en,{"sourceAuthBurst": ["Repeated failures in Linux / device logs", "Validate the account, device, client IP and authentication realm. Stale credentials and approved tests can match."], "sourceAuthSuccess": ["Successful access after repeated failures", "Review the successful source event and subsequent activity. The same complete correlation key and strictly later time are required; this does not confirm compromise."], "linuxRootSSH": ["SSH accepted a root login", "Validate authorization and whether direct root SSH access meets the hardening policy."], "privilegedCommand": ["Sensitive Linux administrative command", "Inspect the source command, sudo authorization, audit user ID and actual outcome. Effects are not confirmed from command text."], "auditChange": ["Linux audit configuration event", "Compare the operation/result with authorized audit maintenance and central copies."], "networkConfig": ["Network-device configuration / command event", "Validate the operator, change ticket, command and result. A submitted, failed or unauthorized action is not proof of an applied configuration."], "networkThreat": ["Vendor-reported network threat", "Check the signature, source/destination, action and later sessions. A blocked detection does not prove endpoint compromise."], "deniedBurst": ["Repeated denied traffic across targets", "Check approved scans, misconfiguration and source ownership. Counts are log records, not packets; scan attribution requires validation."]});
  Object.assign(words.ro,{"lead": "Analizează jurnale Windows, Linux și de echipamente de rețea, reconstruiește cronologia și verifică dovezile din spatele tiparelor suspecte.", "files": "Fișiere locale XML / JSON / NDJSON / CSV / syslog", "formatsHint": "Maximum 8 fișiere, 10 MiB cumulat și 20.000 de evenimente. Subseturi native: Windows, Linux, FortiOS, PAN-OS, Check Point Log Exporter, Cisco ASA/FTD și IOS/IOS XE. Tabelul de mai jos arată formatele acceptate. EVTX binar necesită conversie; schemele SIEM, CEF/LEEF și formatele personalizate nu sunt deduse.", "schemaHint": "Windows folosește eventId, provider, channel și data. Evenimentele v2 reutilizabile includ și platform. JSON/CSV vendor folosește câmpurile sursei sau selectarea explicită a sursei. Timestampurile trebuie să aibă Z/offset. Datele locale syslog/PAN-OS necesită offsetul UTC corect; syslogul vechi necesită și anul.", "sourceMode": "Sursa jurnalelor", "autoSource": "Detectare automată", "contextLabel": "Context de import pentru oră / host incomplet", "contextHint": "Opțional. Introdu offsetul UTC real și anul evenimentelor exportate, nu fusul browserului. Se aplică tuturor fișierelor din analiză, doar unde datele lipsesc; separă importurile dacă echipamentele folosesc offseturi diferite. Offsetul este fix și nu deduce schimbările de oră de vară. Fără context, evenimentele nu intră în corelările temporale.", "timezone": "Offset UTC (exemplu +03:00)", "year": "An pentru syslog vechi", "evidenceHost": "Host când lipsește din jurnal", "platform": "Platformă", "platformGuide": "Acoperirea surselor", "linuxCollect": "Export Linux doar pentru citire", "linuxCollectHint": "Exportă jurnalele locale deja colectate. Conținutul SSH/sudo și înregistrările auditd depind de loggingul disponibil pe acel sistem. Alege un interval limitat potrivit cazului.", "linuxDemo": "Laborator Linux SSH / sudo", "fortinetDemo": "Laborator FortiOS", "paloaltoDemo": "Laborator PAN-OS", "checkpointDemo": "Laborator Check Point", "cisco-iosDemo": "Laborator Cisco IOS / IOS XE", "cisco-asaDemo": "Laborator Cisco ASA / FTD", "sourceCounts": "Platforme importate", "windowsScope": "Security, Sysmon, PowerShell și Defender în XML/JSON/CSV. EVTX binar necesită conversie.", "linuxScope": "journalctl JSON/NDJSON; syslog sshd/sudo; auditd USER_AUTH, USER_LOGIN, USER_CMD și CONFIG_CHANGE. Alte înregistrări audit rămân context, fără reconstrucția evenimentelor kernel.", "fortinetScope": "FortiOS text key=value sau JSON/CSV echivalent: autentificări admin, configurație, trafic respins și anumite evenimente UTM.", "paloaltoScope": "CSV syslog PAN-OS implicit: SYSTEM, CONFIG, TRAFFIC și THREAT; JSON/CSV cu câmpuri numite echivalente. Formatele poziționale personalizate nu sunt mapate. Autentificările din textul SYSTEM rămân context.", "checkpointScope": "Log Exporter JSON/CSV plat sau syslog key:value separat prin punct și virgulă, cu Check Point selectat. Revizie amenințări/trafic respins; auditul rămâne context. Fără CEF/LEEF sau fișiere SmartConsole binare.", "ciscoScope": "Mesaje ASA/FTD %ASA/%FTD și IOS/IOS XE %SEC_LOGIN, %SYS-CONFIG_I, %PARSER-CFGLOG_LOGGEDCMD. Anumite evenimente AAA, trafic respins și comenzi; fără import universal Cisco/ISE/FMC.", "contextCounts": "Evenimente cu context de import furnizat"});
