  Object.assign(rules.ro,{"sourceAuthBurst": ["Autentificări eșuate în jurnale Linux / echipamente", "Verifică utilizatorul, echipamentul, IP-ul client și contextul autentificării. Parole expirate și teste aprobate pot corespunde."], "sourceAuthSuccess": ["Acces reușit după eșecuri repetate", "Verifică evenimentul de succes și activitatea ulterioară. Corelarea cere aceeași cheie completă și un succes strict ulterior; nu confirmă compromiterea."], "linuxRootSSH": ["Autentificare SSH acceptată pentru root", "Validează autorizarea și dacă accesul SSH direct ca root respectă politica de hardening."], "privilegedCommand": ["Comandă administrativă Linux sensibilă", "Inspectează comanda sursă, autorizarea sudo, ID-ul utilizatorului audit și rezultatul real. Efectele nu sunt confirmate din textul comenzii."], "auditChange": ["Eveniment de configurare Linux audit", "Compară operația și rezultatul cu mentenanța audit autorizată și copiile centralizate."], "networkConfig": ["Configurație / comandă pe echipament de rețea", "Verifică operatorul, tichetul, comanda și rezultatul. O acțiune trimisă, eșuată sau neautorizată nu dovedește aplicarea configurației."], "networkThreat": ["Amenințare raportată de vendor", "Verifică semnătura, sursa/destinația, acțiunea și sesiunile ulterioare. O detecție blocată nu dovedește compromiterea stației."], "deniedBurst": ["Trafic respins repetat către mai multe ținte", "Verifică scanări aprobate, configurații greșite și titularul sursei. Sunt numărate înregistrări de jurnal, nu pachete; atribuirea unei scanări necesită validare."]});
  Object.assign(words.fr,{"lead": "Analysez les journaux Windows, Linux et des équipements réseau, reconstruisez la chronologie et examinez les preuves des motifs suspects.", "files": "Fichiers locaux XML / JSON / NDJSON / CSV / syslog", "formatsHint": "Maximum 8 fichiers, 10 MiB cumulés et 20 000 événements. Sous-ensembles natifs : Windows, Linux, FortiOS, PAN-OS, Check Point Log Exporter, Cisco ASA/FTD et IOS/IOS XE. Voir les formats ci-dessous. EVTX binaire à convertir ; schémas SIEM arbitraires, CEF/LEEF et formats personnalisés non déduits.", "schemaHint": "Windows utilise eventId, provider, channel et data. Les événements v2 incluent platform. Le JSON/CSV fournisseur utilise les champs documentés ou une source explicite. Utilisez Z/décalage dans les heures. Les dates syslog/PAN-OS locales nécessitent le décalage UTC ; syslog ancien nécessite aussi l’année.", "sourceMode": "Source des journaux", "autoSource": "Détection automatique", "contextLabel": "Contexte d’import pour heure / hôte incomplet", "contextHint": "Facultatif. Indiquez le décalage UTC réel et l’année des événements, pas le fuseau du navigateur. Valable pour tous les fichiers, uniquement pour les valeurs absentes ; séparez les imports avec des décalages différents. Le décalage fixe ne déduit pas les changements d’heure saisonniers. Les heures non résolues sont exclues des corrélations.", "timezone": "Décalage UTC (exemple +03:00)", "year": "Année du syslog ancien", "evidenceHost": "Hôte absent du journal", "platform": "Plateforme", "platformGuide": "Couverture des sources", "linuxCollect": "Export Linux en lecture seule", "linuxCollectHint": "Exportez les journaux locaux déjà collectés. Les messages SSH/sudo et auditd dépendent de la journalisation disponible. Choisissez un intervalle limité adapté au dossier.", "linuxDemo": "Laboratoire Linux SSH / sudo", "fortinetDemo": "Laboratoire FortiOS", "paloaltoDemo": "Laboratoire PAN-OS", "checkpointDemo": "Laboratoire Check Point", "cisco-iosDemo": "Laboratoire Cisco IOS / IOS XE", "cisco-asaDemo": "Laboratoire Cisco ASA / FTD", "sourceCounts": "Plateformes importées", "windowsScope": "Security, Sysmon, PowerShell et Defender en XML/JSON/CSV. Conversion des EVTX binaires nécessaire.", "linuxScope": "journalctl JSON/NDJSON ; syslog sshd/sudo ; auditd USER_AUTH, USER_LOGIN, USER_CMD et CONFIG_CHANGE. Autres enregistrements conservés en contexte, sans reconstruction des événements noyau.", "fortinetScope": "FortiOS key=value ou JSON/CSV plat équivalent : connexions admin, configuration, trafic refusé et certains événements UTM.", "paloaltoScope": "CSV syslog PAN-OS par défaut : SYSTEM, CONFIG, TRAFFIC et THREAT ; JSON/CSV nommé équivalent. Formats positionnels personnalisés non mappés. Le texte d’authentification SYSTEM reste du contexte.", "checkpointScope": "Log Exporter JSON/CSV plat ou syslog key:value séparé par point-virgule avec Check Point sélectionné. Menaces/trafic refusé ; audit conservé en contexte. Sans CEF/LEEF ni fichiers SmartConsole binaires.", "ciscoScope": "ASA/FTD %ASA/%FTD et IOS/IOS XE %SEC_LOGIN, %SYS-CONFIG_I, %PARSER-CFGLOG_LOGGEDCMD. Certains événements AAA, trafic refusé et commandes ; pas d’import universel Cisco/ISE/FMC.", "contextCounts": "Événements avec contexte fourni"});
