  Object.assign(rules.fr,{"sourceAuthBurst": ["Échecs répétés dans les journaux Linux / réseau", "Validez le compte, l’équipement, l’IP client et le domaine d’authentification. Identifiants obsolètes et tests approuvés peuvent correspondre."], "sourceAuthSuccess": ["Accès réussi après des échecs répétés", "Examinez l’événement de succès et l’activité suivante. La clé complète doit correspondre et le succès être strictement ultérieur ; aucune compromission confirmée."], "linuxRootSSH": ["Connexion SSH root acceptée", "Validez l’autorisation et la conformité de l’accès SSH root direct à la politique de durcissement."], "privilegedCommand": ["Commande Linux administrative sensible", "Examinez la commande, l’autorisation sudo, l’ID utilisateur audit et le résultat réel. Le texte ne confirme pas les effets."], "auditChange": ["Événement de configuration Linux audit", "Comparez l’opération et le résultat à la maintenance autorisée et aux copies centralisées."], "networkConfig": ["Événement de configuration / commande réseau", "Validez l’opérateur, le ticket, la commande et le résultat. Une action soumise, échouée ou non autorisée ne prouve pas son application."], "networkThreat": ["Menace réseau signalée par le fournisseur", "Vérifiez la signature, les adresses, l’action et les sessions suivantes. Une détection bloquée ne prouve pas une compromission."], "deniedBurst": ["Trafic refusé répété vers plusieurs cibles", "Vérifiez les scans approuvés, erreurs de configuration et la source. Comptage de journaux, pas de paquets ; attribution à valider."]});

