  const workspace=window.IncidentWorkspace;
  let view='summary',entities=[],selectedEntity=null;
  function setView(next){
    view=['summary','evidence','steps'].includes(next)?next:'summary';
    for(const name of ['summary','evidence','steps']){$('it-panel-'+name).hidden=name!==view;$('it-view-'+name).setAttribute('aria-pressed',String(name===view));}
  }
  function summaryHTML(r){
    const o=workspace.overview(r,reviews),s=r.summary,platforms=(r.platforms||[]).filter(p=>p.events);
    const facts='<p>'+esc(t().unique)+': <strong>'+s.unique+'</strong> · '+esc(t().hosts)+': '+s.hosts+' · '+esc(t().user)+': '+s.users+'</p><p>'+platforms.map(p=>esc(platformNames[p.platform])+': '+p.events).join(' · ')+'</p><p>'+esc(t().period)+': '+esc(time(s.start))+' → '+esc(time(s.end))+'</p>';
    const gaps=[['rejected',o.rejected],['timeMissing',o.missingTime],['unknown',o.unknown],['omitted',o.omitted]].filter(([,n])=>n).map(([k,n])=>'<li>'+esc(t()[k])+': '+n+'</li>');
    if(o.missingFields.length)gaps.push('<li>'+esc(t().missingRules)+': '+o.missingFields.length+'</li>');
    return '<p class="it-hint">'+esc(t().summaryHint)+'</p><div class="it-overview"><article class="it-card"><h4>'+esc(t().observed)+'</h4>'+facts+'</article><article class="it-card"><h4>'+esc(t().interpretation)+'</h4><p>'+esc(t().high)+': '+s.high+' · '+esc(t().medium)+': '+s.medium+'</p><p>'+esc(t().assessmentHint)+'</p></article><article class="it-card"><h4>'+esc(t().gaps)+'</h4>'+(gaps.length?'<ul>'+gaps.join('')+'</ul>':'<p>'+esc(t().gapNone)+'</p>')+'</article><article class="it-card"><h4>'+esc(t().reviewProgress)+'</h4><p>'+['pending','followup','explained'].map(k=>esc(t()[k])+': '+o.states[k]).join('<br>')+'</p><p>'+esc(t().reviewHint)+'</p></article></div><h4>'+esc(t().topFindings)+'</h4>'+(o.active.length?'<ol class="it-priority-list">'+o.active.slice(0,5).map(f=>'<li><strong>'+esc(ruleWords(f.ruleId)[0])+'</strong> · '+esc(t()[f.priority])+'<small>'+esc(f.host||'?')+' · '+esc(time(f.start))+(f.end&&f.end!==f.start?' → '+esc(f.end):'')+' · '+f.eventRefs.length+' '+esc(t().occurrences)+'</small></li>').join('')+'</ol>':'<p>'+esc(t().noActive)+'</p>');
  }
  function stepsHTML(r){
    const o=workspace.overview(r,reviews),steps=[];
    if(o.rejected||o.missingTime||o.unknown||o.omitted||o.missingFields.length)steps.push([t().dataQuality,t().qualityAdvice]);
    steps.push([t().baseline,t().baselineAdvice]);for(const id of o.ruleIds)steps.push(ruleWords(id));steps.push([t().conclusion,t().conclusionAdvice]);
    return '<p class="it-hint">'+esc(t().nextHint)+'</p><ol class="it-next-list">'+steps.map(([title,advice])=>'<li><strong>'+esc(title)+'</strong><p>'+esc(advice)+'</p></li>').join('')+'</ol>';
  }
  function updateOverview(){if(!report)return;$('it-summary').innerHTML=summaryHTML(report);$('it-next-steps').innerHTML=stepsHTML(report);}
  function renderEntities(){
    if(!report)return;const kind=$('it-entity-type').value||'all',q=$('it-entity-query').value.trim().toLowerCase();
    const items=entities.filter(x=>(kind==='all'||x.type===kind)&&(!q||x.value.toLowerCase().includes(q)));
    $('it-entity-count').textContent=Math.min(100,items.length)+' / '+items.length;
    $('it-entity-list').innerHTML='<div class="it-table-wrap"><table class="it-table"><thead><tr>'+['entityType','entityQuery','occurrences','linked','platform'].map(k=>'<th>'+esc(t()[k])+'</th>').join('')+'</tr></thead><tbody>'+items.slice(0,100).map(x=>'<tr><td>'+esc(t()[x.type])+'</td><td><button type="button" data-it-entity="'+entities.indexOf(x)+'" aria-label="'+esc(t().entityGo+': '+x.value)+'">'+esc(x.value)+'</button></td><td>'+x.eventRefs.length+'</td><td>'+x.matched+'</td><td>'+x.platforms.map(p=>esc(platformNames[p]||p)).join(' · ')+'</td></tr>').join('')+'</tbody></table></div>';
  }
  function selectedRefs(){return selectedEntity?new Set(selectedEntity.eventRefs):null;}
  function renderSelection(){const box=$('it-entity-selection');box.hidden=!selectedEntity;$('it-entity-selected').textContent=selectedEntity?t().entitySelected+': '+t()[selectedEntity.type]+' · '+selectedEntity.value:'';}
  function resetFilters(){$('it-priority').value='all';$('it-host').value='all';$('it-platform').value='all';$('it-search').value='';$('it-matched').checked=false;selectedEntity=null;$('it-entity-type').value='all';$('it-entity-query').value='';}
